CREATE OR REPLACE FUNCTION get_trader_omi_distribution(p_trader_ref character varying)
RETURNS TABLE (trader_id character varying, transaction_count bigint, avg_omi numeric, min_omi numeric, max_omi numeric, stddev_omi numeric) AS $$
BEGIN
    RETURN QUERY
    SELECT t.tradereg::varchar, COUNT(*)::bigint, AVG(r.modfreq / (1 - r.cancelpct))::numeric, MIN(r.modfreq / (1 - r.cancelpct))::numeric, MAX(r.modfreq / (1 - r.cancelpct))::numeric, STDDEV(r.modfreq / (1 - r.cancelpct))::numeric
    FROM trader t JOIN transactionrecord r ON t.tradereg = r.trdref
    WHERE t.tradereg = p_trader_ref
    GROUP BY t.tradereg;
END;
$$ LANGUAGE plpgsql;

