RETURNS TABLE (trader_id varchar, transaction_count bigint, avg_omi numeric, min_omi numeric, max_omi numeric, stddev_omi numeric)
AS $$
BEGIN
    RETURN QUERY EXECUTE 'SELECT t.tradereg, COUNT(*), AVG(r.modfreq / (1 - r.cancelpct)), MIN(r.modfreq / (1 - r.cancelpct)), MAX(r.modfreq / (1 - r.cancelpct)), STDDEV(r.modfreq / (1 - r.cancelpct)) FROM trader t JOIN transactionrecord r ON t.tradereg = r.trdref WHERE t.tradereg = $1 GROUP BY t.tradereg' USING p_trader_id;
END;
$$ LANGUAGE plpgsql;

